const root = process.cwd( );
for (const asset of embeddedAssets) {
  const destination = resolve(root, asset.path);
  const rel = relative(root, destination);
  if (isAbsolute(rel) || rel.startsWith('..')) throw new Error(`Unsafe output path: ${asset.path}`);
  const bytes = gunzipSync(Buffer.from(asset.gzipBase64.replace(/\s/g, ''), 'base64'));
  const actualHash = createHash('sha256').update(bytes).digest('hex');
  if (actualHash !== asset.sha256) throw new Error(`Corrupt embedded asset: ${asset.path}`);
  mkdirSync(dirname(destination), { recursive: true });
  writeFileSync(destination, bytes);
  console.log(`Restored ${asset.path}: ${bytes.length} bytes; SHA-256 verified`);
}
